import { isPatchablePath } from '../core/patch';

const FORBIDDEN_SEGMENTS = new Set([
  'node_modules',
  '.git',
  '.github',
  '.gitlab',
  '.circleci',
  '.cargo',
  '.venv',
  'venv',
  'target',
  'vendor',
  '__pycache__',
]);

/** Lockfiles are regenerated by tools; credential and CI files need explicit human review. */
const FORBIDDEN_FILE_RE =
  /(^|\/)(package-lock\.json|npm-shrinkwrap\.json|yarn\.lock|pnpm-lock\.yaml|Cargo\.lock|poetry\.lock|uv\.lock|Pipfile\.lock|go\.sum|gradle\.lockfile|\.env(\.[\w.-]+)?|\.npmrc|\.pypirc|\.netrc|\.git-credentials|id_rsa[\w.-]*|[\w.-]+\.(pem|key|p12|pfx)|Jenkinsfile|\.gitlab-ci\.yml)$/i;

export function isAllowedLlmPath(p: string): boolean {
  if (!isPatchablePath(p)) return false;
  const segs = p.split('/');
  if (segs.some((s) => FORBIDDEN_SEGMENTS.has(s))) return false;
  return !FORBIDDEN_FILE_RE.test(p);
}
